            new Quote { Id = "https://uk.wikiquote.org/wiki/Марко_Вовчок", Text = "Як це все цікаво складається: і любов, і сльози, і багатий жених, і піднесені почуття.", Author = "Марко Вовчок" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Марко_Вовчок", Text = "І морено, й мучено нас — та все дурницею. І те вчи, і друге, й десяте, й п'яте... товчи та товчи, та й товчи!.. Нащо мені те знати, як по небу зорі ходять або як люди живуть поза морями та чи в їх добре там, та чи в їх недобре там? Аби я знала, чим мені себе між людьми показати...", Author = "Марко Вовчок" },
