            new Quote { Id = "https://uk.wikiquote.org/wiki/Марко_Вовчок", Text = "Тоді напала на мене туга ревная, невсипуща, невгавуща, лихая і невмолимая — вона мене пхала кудись пріч, далі, далеко... Вона мене з місця пхала за двері, гнала улицею, провадила степами, полями, лісами, гаями.", Author = "Марко Вовчок" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Марко_Вовчок", Text = "Якраз з наших вікон видно було дорогу, шляшок битий звивався до міста, — у місті я бував [...] Так вився ж той шляшок кудись далі за те місто... І поверзлось мені, що оце і є він, шлях мій, що аби я ним пішов, то усе б собі знайшов...", Author = "Марко Вовчок" },
            new Quote { Id = "https://uk.wikiquote.org/wiki/Марко_Вовчок", Text = "Уперше портрет і біографію авторки надрукували лише в київському виданні 1901-1903 року. Доти Марко Вовчок забороняє пресі оприлюднювати будь-які відомості про себе, в тому числі й насамперед – друкувати портрети. […] ''«Біографію тільки тоді слід писати, коли людина в могилі й могила тричі травою поросла, а поки людина жива, біографія передчасна»'', – постулює авторка «Живої душі», гігантського біографічного роману з російськомовної й жахливо багатослівної частини спадку.", Author = "Ганна Улюра" },
